// tencentcloud-sdk-nodejs的版本要求大于或等于4.0.3
const tencentcloud = require('tencentcloud-sdk-nodejs');
const express = require('express');
const cors = require('cors');
const port = 3000;

const app = express();
app.use(cors()); // 允许所有来源的跨域请求，生产环境中请根据需要进行配置
const CccClient = tencentcloud.ccc.v20200210.Client;

// 登录腾讯云CCC
app.use('/loginTCCC', (req, res) => {
    const clientConfig = {
    // secret获取地址: https://console.cloud.tencent.com/cam/capi
    credential: {
    // secretId: process.env.TENCENTCLOUD_SECRET_ID,
    // secretKey: process.env.TENCENTCLOUD_SECRET_KEY,
    secretId: "AKIDypTt6A3kDSXQDoBLI3kEWdWEiz2GJAoF",
    secretKey: "GH5f2EDQREqFG5g5GG4mHhvviHeomaDc",
    },
    region: '',
    profile: {
      httpProfile: {
        endpoint: 'ccc.tencentcloudapi.com'
      }
     }
   };
   const client = new CccClient(clientConfig);
   const params = {
     SdkAppId: 1600075019,  // 请替换为自己的 SdkAppId
     SeatUserId: '359824901@qq.com'  // 替换为座席账号
   };
   client.CreateSDKLoginToken(params).then(
     (data) => {
       res.send({
         SdkURL: data.SdkURL
       })
    },
      (err) => {
          console.error('error', err);
          res.status(500);
       }
    );
})

app.post('/loginTCCC', (req, res) => {
  const params = {
      SdkAppId: 1600075019,  // 请替换为自己的 SdkAppId
      SeatUserId: '359824901@qq.com'  // 替换为座席账号
  };

  client.CreateSDKLoginToken(params).then(
      (data) => {
          res.send({
              SdkURL: data.SdkURL  // 返回给前端
          });
      },
      (err) => {
          console.error('错误:', err);
          res.status(500).send('获取SdkURL失败');
      }
  );
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`服务器正在运行在 port ${PORT}`);
});